def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != 0:
                for dr in range(h):
                    for dc in range(w):
                        if grid[dr][dc] == 0:
                            out[3*r + dr][3*c + dc] = value
    return out
